#ifndef TMCE_REGISTRY_H
#define TMCE_REGISTRY_H

/*
 * Table of the TM-CE units linked into the overlay. TM-CE loads each event
 * as a relocatable file and reads its function table (evFunction or
 * cssFunction) out of it; the native build links every unit in and looks the
 * table up here instead. Generated by tools/overlay_build.py from
 * src/tmce/units.txt (build/overlay/tmce/tmce_registry.c).
 */

#define TMCE_MAX_EXPORTS 8

typedef struct TmceModule {
    const char* name;  /* unit name, the file is TM/<name>.dat */
    const char* table; /* "evFunction" or "cssFunction" */
    int count;         /* number of entries in funcs */
    void* funcs[TMCE_MAX_EXPORTS]; /* in table order; NULL if not defined */
} TmceModule;

extern const TmceModule tmce_modules[];
extern const int tmce_module_count;

#endif
